# Run from the repository root: Rscript tools/build-standalone.R [--check]
parts <- c("R/binary.R", "R/jrp.R", "R/read.R")
notices <- c("LICENSE.md", "inst/NOTICE", "inst/LICENSES/jmp-convert-MIT.txt",
             "inst/LICENSES/JMPReader-MIT.txt")
read_utf8 <- function(path) readLines(path, encoding = "UTF-8", warn = FALSE)
lines <- c(
  "# jmp2r: standalone reader, generated by tools/build-standalone.R.",
  "# Edit the files in R/ and regenerate; do not edit this file directly.",
  "# https://github.com/eisuke-inoue386/jmp2r",
  "# Requires R >= 4.1.0. No additional files or packages are downloaded.",
  unlist(lapply(notices, function(path) c("#", paste0("# ", read_utf8(path)))),
         use.names = FALSE),
  "",
  unlist(lapply(parts, function(path)
    c(paste0("# ---- ", path, " ----"), read_utf8(path), "")), use.names = FALSE)
)
lines[lines == "# "] <- "#"
while (length(lines) && tail(lines, 1L) == "") lines <- head(lines, -1L)
expected <- charToRaw(enc2utf8(paste0(paste(lines, collapse = "\n"), "\n")))
target <- "jmp2r.R"
if ("--check" %in% commandArgs(trailingOnly = TRUE)) {
  if (!file.exists(target) ||
      !identical(readBin(target, "raw", n = file.info(target)$size), expected)) {
    stop("jmp2r.R is out of date. Run Rscript tools/build-standalone.R and commit it.")
  }
  cat("Standalone file is up to date.\n")
} else {
  writeBin(expected, target)
  cat("Generated jmp2r.R.\n")
}
